/* One journal key makes a two-list import visible as a single operation. */
window.GakuTransfer=(()=>{
 const KEYS={kotoba:'gaku-ui-data',kanji:'gaku-ui-kanji'},JOURNAL='gaku-data-import-journal-v1',FORMAT='dex-gaku-custom-data',MAX_BYTES=5*1024*1024,MAX_ROWS=5000;
 const own=(o,k)=>Object.prototype.hasOwnProperty.call(o,k);
 function journal(){const raw=localStorage.getItem(JOURNAL);if(raw===null)return null;const j=JSON.parse(raw);if(!j||j.version!==1||!['prepared','committed'].includes(j.state)||!j.before||!j.after)throw Error('Catatan pemulihan belum dapat dibaca.');for(const side of ['before','after'])for(const k of Object.keys(KEYS))if(j[side][k]!==null&&typeof j[side][k]!=='string')throw Error('Catatan pemulihan tidak sesuai.');return j}
 function raw(kind){if(!own(KEYS,kind))throw Error('Jenis data tidak dikenal.');const j=journal();return j?j[j.state==='committed'?'after':'before'][kind]:localStorage.getItem(KEYS[kind])}
 function snapshot(){return Object.fromEntries(Object.keys(KEYS).map(k=>[k,raw(k)]))}
 function pending(){try{return journal()?.state||null}catch{return 'broken'}}
 function settle(){try{const j=journal();if(!j)return true;const values=j.state==='committed'?j.after:j.before;for(const k of Object.keys(KEYS)){if(values[k]===null)localStorage.removeItem(KEYS[k]);else localStorage.setItem(KEYS[k],values[k])}for(const k of Object.keys(KEYS))if(localStorage.getItem(KEYS[k])!==values[k])return false;localStorage.removeItem(JOURNAL);return true}catch{return false}}
 function commit(after,before){if(!settle())return {ok:false,message:'Penyimpanan belum bisa dipulihkan. Data tetap tersedia; coba lagi setelah ruang penyimpanan cukup.'};if(Object.keys(KEYS).some(k=>localStorage.getItem(KEYS[k])!==before[k]))return {ok:false,changed:true};const j={version:1,state:'prepared',before,after};try{localStorage.setItem(JOURNAL,JSON.stringify(j));j.state='committed';localStorage.setItem(JOURNAL,JSON.stringify(j))}catch{settle();return {ok:false,message:'Impor belum tersimpan. Data sebelumnya tetap dipertahankan. Periksa ruang penyimpanan browser.'}}const cleaned=settle();return {ok:true,recovery:!cleaned}}
 function text(o,k,max,required=false){const label=({jp:'Kata Jepang',meaning:'Arti',rom:'Romaji',kana:'Bacaan kana',mnemonic:'Jembatan ingatan',radical:'Radikal',word:'Contoh kata'})[k]||k;const value=o[k];if(value===undefined||value===null){if(required)throw Error(label+' wajib diisi.');return ''}if(typeof value!=='string')throw Error(label+' harus berupa teks.');const v=value.trim();if((required&&!v)||v.length>max)throw Error(label+' kosong atau melebihi '+max+' karakter.');return v}
 const kana=/^[\p{Script=Hiragana}\p{Script=Katakana}ー.・\-\s]+$/u;
 function normalize(row,kind){if(!row||typeof row!=='object'||Array.isArray(row))throw Error('Baris harus berupa objek data.');const out={jp:text(row,'jp',60,true).normalize('NFKC'),meaning:text(row,'meaning',120,true),level:row.level};if(!['N5','N4'].includes(out.level))throw Error('Level harus N5 atau N4.');if(kind==='kotoba'){out.rom=text(row,'rom',80,true);out.kana=text(row,'kana',80);if(out.kana&&!kana.test(out.kana))throw Error('Bacaan kana harus memakai kana.');if(row.example!==undefined&&row.example!==null){if(typeof row.example!=='object'||Array.isArray(row.example))throw Error('Contoh kalimat tidak sesuai.');out.example={jp:text(row.example,'jp',500,true),kana:text(row.example,'kana',500,true),meaning:text(row.example,'meaning',500,true)}}}
  else{if(!/^\p{Script=Han}$/u.test(out.jp))throw Error('Isi satu karakter kanji.');for(const key of ['on','kun']){const values=row[key]===undefined?[]:row[key];if(!Array.isArray(values)||values.length>30||values.some(v=>typeof v!=='string'||!v.trim()||v.length>80||!kana.test(v)))throw Error((key==='on'?'On’yomi':'Kun’yomi')+' harus berupa daftar bacaan kana (boleh kosong).');out[key]=values.map(v=>v.trim())}out.mnemonic=text(row,'mnemonic',300);out.radical=text(row,'radical',2);if(out.radical&&!/^\p{Script=Han}$/u.test(out.radical))throw Error('Radikal harus satu karakter.');if(row.strokes!==undefined&&row.strokes!==null&&(!Number.isInteger(row.strokes)||row.strokes<1||row.strokes>64))throw Error('Guratan harus angka 1–64.');out.strokes=row.strokes??null;const examples=row.examples===undefined?[]:row.examples;if(!Array.isArray(examples)||examples.length>2)throw Error('Maksimal dua contoh kata.');out.examples=examples.map(e=>{if(!e||typeof e!=='object'||Array.isArray(e))throw Error('Contoh kata tidak sesuai.');const x={word:text(e,'word',80,true),kana:text(e,'kana',80,true),meaning:text(e,'meaning',120,true)};if(!x.word.includes(out.jp)||!kana.test(x.kana))throw Error('Contoh harus memuat kanji ini dan bacaan kana.');return x})}return {...Object.fromEntries(Object.entries(row).filter(([k])=>!['customId','__proto__','constructor','prototype'].includes(k))),...out}}
 function parse(value){if(typeof value!=='string'||value.length>MAX_BYTES)throw Error('File terlalu besar (maksimal 5 MB).');let o;try{o=JSON.parse(value.replace(/^\uFEFF/,''))}catch{throw Error('File bukan JSON yang dapat dibaca.')}if(!o||o.format!==FORMAT||o.version!==1||!o.data||!Array.isArray(o.data.kotoba)||!Array.isArray(o.data.kanji))throw Error('Format tidak sesuai. Gunakan JSON hasil Ekspor atau contoh format DeX Gaku.');if(o.data.kotoba.length+o.data.kanji.length>MAX_ROWS)throw Error('Maksimal 5.000 baris dalam satu impor.');return o.data}
 function plan(input,records,base){const result={rows:[],add:{kotoba:[],kanji:[]},counts:{new:0,duplicate:0,invalid:0}},seen={kotoba:new Set(),kanji:new Set()};const key=(r,k)=>k==='kotoba'?r.level+'|'+kotobaWritten(r.jp):kotobaWritten(r.jp);for(const k of Object.keys(KEYS)){for(const r of base[k])seen[k].add(key(r,k));for(const r of records[k])seen[k].add(key({...r,level:r.level||'N5'},k));for(let i=0;i<input[k].length;i++){const raw=input[k][i];let status='new',message='Siap ditambahkan.',row=null;try{row=normalize(raw,k);const tag=key(row,k);if(seen[k].has(tag)){status='duplicate';message='Sudah ada di materi, data buatanmu, atau baris sebelumnya.'}else{seen[k].add(tag);result.add[k].push(row)}}catch(e){status='invalid';message=e.message}result.counts[status]++;result.rows.push({kind:k,index:i+1,status,message,jp:row?.jp||(typeof raw?.jp==='string'?raw.jp.slice(0,80):'Baris '+(i+1)),level:row?.level||'',meaning:row?.meaning||(typeof raw?.meaning==='string'?raw.meaning.slice(0,120):''),reading:row?(k==='kotoba'?(row.kana||row.rom):[...row.on,...row.kun].join(' · ')):''})}}return result}
 function exportObject(records,kind='all',level='all'){const data={kotoba:[],kanji:[]};for(const k of Object.keys(KEYS))if(kind==='all'||kind===k)data[k]=records[k].filter(r=>level==='all'||(r.level||'N5')===level).map(r=>({...r,level:r.level||'N5'}));return {format:FORMAT,version:1,exportedAt:new Date().toISOString(),data}}
 return {KEYS,JOURNAL,FORMAT,MAX_BYTES,MAX_ROWS,raw,snapshot,pending,settle,commit,normalize,parse,plan,exportObject};
})();
